# NOTE: Assertions have been autogenerated by utils/update_mca_test_checks.py
# RUN: llvm-mca -mtriple=mips64el -mcpu=r5900 -iterations=100 \
# RUN:   -instruction-info=false -resource-pressure=false < %s | FileCheck %s

# The R5900 issues two instructions per cycle into pipe 0 (FPU operations,
# multiply/divide) and pipe 1 (loads, stores, FPU loads/stores/moves); ALU
# instructions use either pipe. All FPU instructions share one COP1 slot.
# The cycle counts match measurements on hardware.

# Two ALU instructions pair: 1 cycle per iteration.
# LLVM-MCA-BEGIN alu-alu
addu $9, $10, $11
addu $12, $10, $11
# LLVM-MCA-END

# One load per cycle: 2 cycles.
# LLVM-MCA-BEGIN lw-lw
lw $9, 0($4)
lw $10, 4($4)
# LLVM-MCA-END

# A load pairs with an FPU operation: 1 cycle.
# LLVM-MCA-BEGIN lw-mul.s
lw $9, 0($4)
mul.s $f0, $f8, $f9
# LLVM-MCA-END

# An FPU load does not, both use the COP1 slot: 2 cycles.
# LLVM-MCA-BEGIN lwc1-mul.s
lwc1 $f2, 0($4)
mul.s $f0, $f8, $f9
# LLVM-MCA-END

# MULT and FPU operations both issue to pipe 0: 3 cycles.
# LLVM-MCA-BEGIN mult-mul.s
mult $10, $11
mul.s $f0, $f8, $f9
mul.s $f1, $f8, $f9
# LLVM-MCA-END

# MULT holds MAC0 for 2 cycles, but pipe 0 for 1: 2 cycles.
# LLVM-MCA-BEGIN mult-alu
mult $10, $11
addu $12, $10, $11
addu $13, $10, $11
addu $14, $10, $11
# LLVM-MCA-END

# DIV.S holds the COP1 slot for 2 cycles and the divider for 7: 8 cycles.
# LLVM-MCA-BEGIN div.s-add.s
div.s $f0, $f8, $f9
add.s $f1, $f8, $f9
add.s $f2, $f8, $f9
add.s $f3, $f8, $f9
add.s $f4, $f8, $f9
add.s $f5, $f8, $f9
add.s $f6, $f8, $f9
# LLVM-MCA-END

# FPU operation latency is 4: 4 cycles.
# LLVM-MCA-BEGIN add.s-chain
add.s $f0, $f0, $f1
# LLVM-MCA-END

# FPU load latency is 2, the dependent add.s waits: 3 cycles.
# LLVM-MCA-BEGIN lwc1-add.s
lwc1 $f1, 0($4)
add.s $f2, $f1, $f3
# LLVM-MCA-END

# SWC1 reads its FPR one cycle late: 6 cycles.
# LLVM-MCA-BEGIN add.s-swc1
add.s $f1, $f2, $f3
swc1 $f1, 8($4)
# LLVM-MCA-END

# Load-to-address latency is 2: 2 cycles.
# LLVM-MCA-BEGIN lw-chain
lw $4, 0($4)
# LLVM-MCA-END

